**פתרון רשמי** (22A-B עמ' 1):
```c
int f_1(int M[][N]) {
    int i, j, sum;
    for (i = 0; i < N; i++) {
        sum = 0;
        for (j = 0; j < N; j++) {
            sum += M[i][j];
        }
        if (sum - M[i][i] != M[i][i]) return 0;
    }
    return 1;
}
```
לכל שורה מחשבים את סכום כל איבריה, ומחסירים את איבר האלכסון: אם הסכום ללא האלכסון שונה מהאיבר עצמו מחזירים 0. כל תא נקרא פעם אחת, כלומר $O(N^2)$ ביחס למספר התאים.

**פתרון רשמי** (22A-B עמ' 1-2):
```c
int f_11(int M[][N]) {
    int i, j, sum;
    for (j = 0; j < N; j++) {
        sum = 0;
        for (i = 0; i < N; i++) {
            sum += M[i][j];
        }
        if (sum - M[j][j] != M[j][j]) return 0;
    }
    return 1;
}
```
אותו רעיון כמו בסעיף א, כשהלולאה החיצונית רצה על העמודות והפנימית על השורות.

**פתרון רשמי** (22A-B עמ' 2):
```c
int f_2(int *c, int k, int i, int j) {
    if (i == j)
        return -1;
    if (c[i] + c[j] == k) return i;
    if (c[i] + c[j] > k)
        return f_2(c, k, i, j - 1);
    return f_2(c, k, i + 1, j);
}
```
שני מצביעים משני קצות התחום: אם הסכום שווה ל-`k` מחזירים `i`; אם הסכום גדול מדי מקטינים את `j`, אחרת מגדילים את `i`. כשהמצביעים נפגשים (`i == j`) אין זוג ומחזירים `-1`. כל קריאה מצמצמת את התחום באחד, כלומר $O(n)$.

**פתרון רשמי** (22A-B עמ' 3), הפונקציה הראשונה:
```c
int f_3(char* str) {
      int a[26] = { 0 };
      int i = 0;
      while (*str) {
            a[*str - 'a']++;
            if (a[*str - 'a'] > 1) return 0;
            str++;
      }
      while ((i<26) && (a[i] == 0))
            i++;

      while ((i < 26) && (a[i] == 1))
            i++;

      while (i < 26) {
            if (a[i] != 0) return 0;
            i++;
      }
      return 1;
}
```
**או** (גרסה שנייה כפי שמופיעה בפתרון הרשמי, עמ' 3-4):
```c
int f_33(char* str) {
      int count[26] = { 0 };
      int i = 0,j;
      char min='z', max='a';
      while (*str) {
            count[*str - 'a']++;
            if (count[*str - 'a'] > 1) return 0;
            if (min > *str)
                  min = *str;
            else
                  if (max < *str)
                        max = *str;
            str++;
      }

      i = min - 'a';
      j= max - 'a';
      while (i <= j) {
            if (count[i] != 1) return 0;
            i++;
      }
      return 1;
}
```
הגרסה הראשונה סופרת הופעות של כל אות (חזרה מחזירה 0), ואז בודקת שהאותיות שנספרו יוצרות בלוק רציף אחד: מדלגים על אפסים, על אחדים, ואחרי זה כל התאים חייבים להיות 0. סריקה אחת ועוד 26 תאים, כלומר $O(n)$.
**הערה:** בגרסה השנייה המשתנה `max` מתעדכן רק כשהאות אינה מינימום חדש, ולכן למשל עבור "ca" היא מחזירה 1 (`max` נשאר `'a'`) אף שהאות `b` חסרה והתשובה הנכונה 0. הגרסה הראשונה תקינה.

**פתרון רשמי** (22A-B עמ' 4):
```c
int  maxmax(int n) {
    int max, i, num;
    scanf("%d", &max);
    for (i = 0; i < n - 1; i++) {
        scanf("%d", &num);
        if (num > max) {
            printf("%d", num);
            max = num;
        }
    }
}
```
שומרים רק את המקסימום עד כה. הראשון נקלט בנפרד, וכל מספר נוסף שגדול ממנו מודפס והופך למקסימום החדש. קריאה אחת לכל מספר וללא מערך, כלומר $O(n)$ וזיכרון $O(1)$.
